function kahnInputFeeds(k,key){const mapped=(k?.feature_map||[]).filter(f=>(f.inputs||[]).includes(key)).map(f=>f.label),extra=[];for(const m of k?.models||[]){if(m.form!=='two_stage')continue;for(const pm of m.position_models||[]){if(pm.decision_key===key)extra.push(`${pm.decision_label} position`);if(key==='analytics'&&(pm.features||[]).includes('analytics_avg'))extra.push('Service position (older Experience association)');if(key==='analytics'&&(pm.features||[]).includes('online_analytics'))extra.push('Online Investment × Customer Analytics (Frictionless diagnostic)');}}return [...new Set([...mapped,...extra])].join(', ')||'Collapsed';}
function kahnInputUsage(k,key){const used=new Set();for(const m of k?.models||[]){if(m.form==='two_stage'){for(const pm of m.position_models||[]){if(pm.decision_key===key||(key==='analytics'&&(pm.features||[]).some(f=>['analytics_avg','online_analytics'].includes(f))))used.add(m.quadrant);}}else{const mapped=(k?.feature_map||[]).filter(f=>(f.inputs||[]).includes(key));if((m.features||[]).some(f=>mapped.some(x=>x.key===f)))used.add(m.quadrant);}}return [...used].join(', ')||'—';}
function kahnFitPanel(k){const models=k?.models||[];return panel('Section 2 · Kahn matrix: direct fits + two-stage position models','Fifteen distinct workbook input series after collapsing identical quality settings. Brand and Low Price retain their lagged ridge fits; Experience retains its older lagged position fit. Frictionless now has a separate mechanism audit: analytics interacts with online investment, service has no fitted carryover, same-round and lagged timing are compared, and earlier-only validation is shown. Its diagnostic loses to persistence and is not decision-ready. Fourteen inputs enter at least one equation; retail coverage is shown for context, not as a score component.',`<div class="kahn-fit-grid">${models.map(m=>{const maxError=Math.max(...m.predictions.map(p=>Math.abs(p.error))),two=m.form==='two_stage';return `<div class="kahn-fit-card"><div class="evidence-label">${esc(m.quadrant)}</div><div class="kahn-fit-score">${num(m.latest?.actual)} → ${num(m.latest?.fitted)}</div><p>R${m.latest?.round} actual → fitted. ${m.audited?'Earlier-only conditional':'Hide-one-transition'} MAE <strong>${num(m.audited?m.forward_mae:m.hide_one_mae)}</strong> versus ${m.audited?'same-period ':''}persistence <strong>${num(m.audited?m.forward_persistence_mae:m.persistence_mae)}</strong>. Largest fitted error <strong>${num(maxError)}</strong>.</p><p><strong>${two?'Components':'Top 3'}:</strong> ${m.top_factors.map(c=>esc(c.label)).join(' · ')}</p><span class="${m.preferred==='persistence'?'review-badge muted':'review-badge'}">${esc(kahnVerdict(m))}</span></div>`;}).join('')}</div>`+
  table(['Quadrant','Form','Fitted MAE','Hide-one MAE','Persistence R1–R6','Earlier-only R4–R6 diagnostic / persistence','Preferred description'],models.map(m=>[esc(m.quadrant),esc(m.form_label),num(m.fitted_mae),num(m.hide_one_mae),num(m.persistence_mae),m.audited?`${num(m.forward_mae)} / ${num(m.forward_persistence_mae)}`:'Not audited here',esc(kahnVerdict(m))]))+
 `<div class="review-chips">${models.map(m=>`<button type="button" data-kahn-quadrant="${esc(m.quadrant)}" class="${kahnQuadrant===m.quadrant?'selected':''}" aria-pressed="${kahnQuadrant===m.quadrant}">${esc(m.quadrant)}</button>`).join('')}</div><div id="kahn-quadrant-detail">${kahnQuadrantDetail()}</div>`+
 `<details><summary>The 15 distinct input parameters and how they enter the analysis</summary>${table(['Input parameter','Feeds driver','Used by'],(k?.input_keys||[]).map(key=>[esc(key),esc(kahnInputFeeds(k,key)),esc(kahnInputUsage(k,key))]))}<p><strong>Why fifteen, not sixteen:</strong> the workbook contains sixteen decision columns. Private-brand quality and national-brand quality are identical in every observed round, so they are one effective input. The total budget is a derived total, not a decision factor. Fourteen series enter at least one fitted score equation. Retail coverage is retained in the lagged matrix but has no score coefficient here because it is not a documented component of the four ratings. Service intensity and experience intensity are retained as diagnostics; the two-stage model uses relative spending instead.</p><p><strong>Why a fixed penalty:</strong> with only six transitions, tuning λ per equation would fit noise as well as coefficients. λ=${num(k?.penalty)} is fixed for the direct fits and the Stage 1 position equations. The Stage 2 score identity is not fitted. Hide-one-transition checks use that fixed rule.</p></details>`+
  `<details><summary>Legacy lagged input matrix: decisions at R0–R5 (15 columns)</summary>${table(['Decision round',...(k?.input_keys||[])],(data.history_analysis.history||[]).slice(0,6).map(r=>['R'+r.round,...(k?.input_keys||[]).map(key=>['online','service','experience','vendor','analytics'].includes(key)?money(r.decisions[key]):num(r.decisions[key]))]))}<p>National-brand quality is omitted because it is identical to private-brand quality in every observed round. Each column is the actual submitted decision, not a recommendation. Brand, Low Price and the older Experience fit use lagged inputs. The audited Frictionless diagnostic instead uses R1–R6 same-round inputs and prior online position; its audit separately reports one-round-lag timing sensitivity. No alignment is certified simulator mechanics.</p></details>`+
 note(esc(k?.boundary||'Lagged Kahn association only.')));}
function marketValueFitPanel(v,last){if(!v?.predictions?.length)return panel('Section 3 · Market value fit','No complete market-value periods are available.',note(esc(v?.status||'Unavailable')));const maxErr=Math.max(...v.predictions.map(p=>Math.abs(p.error_pct)));return panel('Section 3 · Market value fit: earnings, discount rate and book leverage','The same actual → fitted → error discipline as the WACC page, with a non-circular specification. Book debt weight is used instead of market debt weight because the latter contains reported market value in its denominator.',`<p id="market-value-equation"><strong>${esc(v.equation)}</strong></p><p>Market value is reported in dollars; EBIT is in dollars in the log term; WACC is in percentage points; book debt weight = debt ÷ (debt + book equity). The model is an association, not a forecast or a simulator valuation formula.</p><p>Adding the Kahn deficit index does <strong>not</strong> improve the R5–R6 earlier-period test (10.3% versus 8.0% for the finance model). The selected value fit therefore stays financial; the Kahn fits are an execution diagnostic, not a valuation input.</p>`+
 table(['Metric','Result','Reading'],[['Fitted MAPE',pct(v.fitted_mape),'Average absolute error, all seven periods'],['Hide-one-period MAPE',pct(v.hide_one_mape),'Refit without one period and predict it back'],['R5–R6 earlier-period MAPE',pct(v.forward_mape),'Fit on earlier periods only'],['Previous-period baseline MAPE',pct(v.baseline_mape),'Use the prior market value as the prediction'],['R²',fitR2(v.r_squared),'Share of log-value variation described in-sample']])+
 historyLine('Reported versus fitted market value',v.predictions.map(p=>p.round),[{label:'Reported actual',values:v.predictions.map(p=>p.actual),color:'#7c3aed'},{label:'Fitted, not forecast',values:v.predictions.map(p=>p.fitted),color:'#0891b2',dashed:true}],money,false)+
 table(['Round','Reported actual','Fitted','Error (fitted − actual)'],v.predictions.map(p=>['R'+p.round,money(p.actual),money(p.fitted),signed(p.error_pct,pct)]))+
 note(`Fitted MAPE <strong>${pct(v.fitted_mape)}</strong>; hide-one-period <strong>${pct(v.hide_one_mape)}</strong>; R5–R6 <strong>${pct(v.forward_mape)}</strong> versus <strong>${pct(v.baseline_mape)}</strong> persistence. Largest fitted error ${pct(maxErr)}. These are seven company-periods, so the earlier-period result is encouraging but not a certified forecast.`)+
 `<details><summary>Model comparison and best-performance check</summary>${table(['Specification','Fitted MAPE','Hide-one-period MAPE','R5–R6 MAPE','R²'],v.comparison.map(c=>[esc(c.name),pct(c.fitted_mape),pct(c.hide_one_mape),pct(c.forward_mape),fitR2(c.r_squared)]))}<p>${esc(v.search?.note||'')}</p><p>The selected finance model is not the lowest raw error in every comparison. Service intensity is better in raw hide-one-period and earlier-period error, but it is a decision proxy, so the finance specification is retained for interpretability. The selection is not a claim that this is the true valuation function.</p></details>`+
 `<details><summary>Coefficients and validation detail</summary>${table(['Term','Coefficient'],[['Intercept',num(v.intercept)],...v.coefficients.map(c=>[esc(c.label),num(c.coefficient)])])}${table(['Validation check','Result'],[['Fitted MAPE',pct(v.fitted_mape)],['Hide-one-period MAPE',pct(v.hide_one_mape)],['Earlier-period R5–R6 MAPE',pct(v.forward_mape)],['Persistence baseline',pct(v.baseline_mape)],['Observations',num(v.observations)]])}<p>${esc(v.boundary)}</p></details>`+
 `<details><summary>Supporting checks: accounting recovery and reported-position reconstruction</summary>${table(['Accounting bridge component','Signed contribution'],(data.history_analysis.finance_bridge||[]).map(r=>[esc(r.label),signed(r.value,money)]))}${table(['Quadrant','Reconstruction','Retailer-period checks','Mean absolute error','Maximum error'],(data.history_analysis.reconstruction||[]).map(r=>[esc(r.quadrant),esc(r.components.join(' + ')),num(r.observations),num(r.mean_absolute_error),num(r.max_absolute_error)]))}<p>Experience ≈ shopping-experience position + service position, and Frictionless ≈ online position + service position, within rounding. The Frictionless identity is the same construction used in Section 2. The shared weak component is service. These are output-to-output checks, not spending-response estimates or proof of simulator code.</p></details>`+
 note('No causal claim: EBIT, WACC, book leverage and market value are jointly determined. The model does not say that changing a decision will move value by the coefficient, and it does not replace the simulator’s max(DCF, CLV/private-brand, liquidation) valuation.'));}
function marketValueAnalysis(){const a=data.history_analysis,h=a.history,first=h[0],last=h.at(-1),ka=a.market_value_analysis||{},k=ka.kahn||{},v=ka.value||{};return head(`MARKET VALUE · OBSERVED R0–R${data.current_round}`,'Market value analysis','Fit three Kahn quadrants from lagged decisions, reconstruct Frictionless from its two reported positions, then fit reported market value with the same actual, fitted and error discipline.',offline?'':'<a class="button" href="/market-value-report" download>↓ Download market value HTML</a>')+
 `<div class="cards">${card('REPORTED MARKET VALUE',money(last.market_value),signed(last.market_value/first.market_value-1,pct)+' since R0')}${card('EXPERIENCE LEADER GAP',num(last.quadrants.EXPERIENCE.target_gap),'Target #1; not just above fair value')}${card('FRICTIONLESS FLOOR SHORTFALL',num(last.quadrants.FRICTIONLESS.target_gap),'Reported CSV fair value—not a formula')}${card('OBSERVED MODEL PERIODS',num(v.observations||a.valuation?.observations),'Seven value periods; six lagged decision→rating transitions')}</div>`+
 kahnFitPanel(k)+
 marketValueFitPanel(v,last)+
 historyDiagnosis()+
 sources();}
document.addEventListener('change',e=>{if(e.target.id==='segment-analysis-metric'){segmentAnalysisMetric=e.target.value;$('#segment-analysis-chart').innerHTML=segmentAnalysisChart();}});

let waccFactorKey='low_markup';
function waccModelPanel(){const m=data.wacc_analysis.model;if(m.intercept===undefined)return note('Insufficient periods for a financing model.');const fmt=v=>v===null||v===undefined?'—':num(v);
 return panel('WACC equation: actual, fitted and error','The main accuracy test is simple: compare actual WACC with the fitted value and calculate the error. The hide-one-round check is an optional guard against overfitting.',
  `<p id="wacc-model-equation"><strong>${esc(m.equation)}</strong></p><p><strong>Anchored at R${m.anchor_round}:</strong> ${esc(m.centered_equation)}</p><p>Market debt weight = debt ÷ (debt + reported equity market value). Earnings yield = EBIT ÷ market value. EBIT is in $ millions in the scale term. The model is local to the observed weight range and must not be extrapolated.</p><p>${esc(m.rationale)}</p>`+
  table(['Round','Actual WACC (%)','Fitted (%)','Error (pp)'],m.predictions.map(p=>['R'+p.round,num(p.actual),num(p.fitted),signed(p.fitted-p.actual,v=>Number(v).toFixed(2))]))+
  note(`Fitted MAE = <strong>${num(m.fitted_mae_pp)} pp</strong>; R² = ${fmt(m.r_squared)}; adjusted R² = ${fmt(m.adjusted_r_squared)}. Error = fitted − actual. This is an in-sample fit, so it is not enough on its own.`)+
  table(['Model','Fitted MAE (pp)','Hide-one-round MAE (pp)','Earlier-period MAE (pp)'],m.comparison.map(c=>[esc(c.name),fmt(c.fitted_mae_pp),fmt(c.loo_mae_pp),fmt(c.forward_mae_pp)]))+
  note(m.forward_mae_pp<m.baseline_mae_pp?'The selected model beats the previous equations and the previous-round baseline in the earlier-period comparison. The margin over simple persistence is now wide, but seven periods still cannot prove stable forecast skill.':'The selected model improves fitted and hide-one-round error but does not beat the previous-round baseline in the earlier-period comparison. Treat it as exploratory.')+
  `<details><summary>What is the hide-one-round check?</summary><p>Refit the equation seven times. Each time, hide one round, fit on the other six, and predict the hidden round. The average absolute error is the hide-one-round MAE. It tests whether the equation memorised seven points; it is <strong>not</strong> a Round 7 forecast. The full table above already shows actual, fitted and error, so you can judge the fit directly.</p></details>`+
  `<details><summary>Best-performance confirmation</summary><p>I searched ${num(m.search.candidate_subsets)} feature combinations with ${num(m.search.candidate_penalties)} ridge penalties. The selected three-feature model scores <strong>${num(m.selected_nested_mae_pp)} pp</strong> under hide-one-round selection. Allowing the search to choose a different feature set inside every fold scores <strong>${num(m.search.unrestricted_nested_mae_pp)} pp</strong>—worse, because it chases noise. The best four-feature extension scores <strong>${num(m.search.fourth_feature_best_nested_pp)} pp</strong>, so it is not an improvement.</p>${table(['Specification check','Hide-one-round MAE (pp)'],[['Selected three-feature model',num(m.selected_nested_mae_pp)],['Unrestricted 377-subset search',num(m.search.unrestricted_nested_mae_pp)],['Best four-feature extension',num(m.search.fourth_feature_best_nested_pp)],['Previous two-feature model',num(m.comparison[1].loo_mae_pp)]])}<p>${esc(m.search.note)}</p></details>`+
  `<details><summary>Optimization audit: ridge penalty grid</summary>${table(['λ','Fitted MAE (pp)','Hide-one-round MAE (pp)'],m.tuning.map(t=>[num(t.penalty),num(t.fitted_mae_pp),num(t.loo_mae_pp)]))}<p>λ is chosen only to stabilise coefficients and reduce hide-one-round error. It does not select decision inputs or imply that lower training error is a better business model.</p></details>`+
  `<details><summary>Earlier-period test detail</summary>${table(['Round','Actual (%)','Model (%)','Previous-round baseline (%)'],m.forward.map(p=>['R'+p.round,num(p.actual),num(p.estimate),num(p.persistence)]))}<p>Only R5–R6 are available for this test. Evaluation-period EBIT, market value and debt are observed, not forecast.</p></details>`+note(esc(m.boundary)));}
function waccFactorDetail(){const a=data.wacc_analysis,f=a.factors.find(f=>f.key===waccFactorKey)||a.factors[0],p=f.pathway,wrap=s=>`<div class="wrap">${esc(s)}</div>`,v=f.markup_arithmetic;
 return `<h3>${esc(f.label)}</h3><p><strong>Pathway:</strong> ${esc(p.channel)}</p><p><strong>Potential benefit:</strong> ${esc(p.up)}</p><p><strong>Countervailing risk:</strong> ${esc(p.down)}</p><p><strong>Decision test:</strong> ${esc(p.check)}</p><p class="review-copy">Source: ${esc(p.source)}. Last observed input change: ${f.last_changed_round===null?'none':'R'+f.last_changed_round}; ${f.distinct_settings} distinct settings.</p>`+
 (v?note(`Last-round markup ${num(v.old)}% → ${num(v.new)}%: at fixed unit cost, selling price changes ${signed(v.price_change,pct)} and units could change ${signed(v.units_for_equal_gross_profit,pct)} while preserving gross-profit dollars. This is arithmetic—not observed elasticity, total-profit break-even or a WACC forecast.`):'')+
 `<div class="review-grid">${panel('Input history','Actual submitted values, not suggested settings.',historyLine(f.label,a.history.map(r=>r.round),[{label:f.label,values:f.history.map(r=>r.value),color:'#7c3aed'}],n=>factorValue(n,f.unit)))}${panel('Reported WACC history','Separate units/axis; visually similar trends are not causality.',historyLine('Reported WACC',a.history.map(r=>r.round),[{label:'Reported WACC (%)',values:a.history.map(r=>r.wacc),color:'#d97706'}],n=>num(n)+'%'))}</div>`+
 table(['Transition','Input before → after','Input change','WACC change (pp)','Debt change','Inventory change','EBIT change','Other factors changed'],f.change_evidence.map(t=>['R'+t.from_round+'→R'+t.round,factorValue(a.history[t.from_round].decisions[f.key],f.unit)+' → '+factorValue(a.history[t.round].decisions[f.key],f.unit),signed(t.changes[f.key],n=>factorValue(n,f.unit)),signed(t.wacc_change_pp),signed(t.debt_change,money),signed(t.inventory_change,money),signed(t.ebit_change,money),num(t.other_changed_factors)]))+
 note('Other simultaneous changes, delayed effects and competitors prevent attributing the WACC move to this factor. A factor held constant while WACC moves cannot by itself explain that period’s change; retained or interacting effects can still matter.');}
let waccDebateGroup='markup',waccDebateLens='mechanism';
const WACC_DEBATE_GROUPS=[['markup','Price markup'],['breadth','Breadth'],['depth','Depth'],['private','Private-brand mix'],['quality','Quality']];
const WACC_DEBATE_LENSES=[['mechanism','How it reaches WACC'],['upside','Potential benefit'],['risk','Why it can backfire'],['test','What to test']];
function waccDebateDetail(){const a=data.wacc_analysis,factors=a.factors.filter(f=>f.group===waccDebateGroup),f=factors[0],p=f.pathway;
 const content={mechanism:p.channel,upside:p.up,risk:p.down,test:p.check}[waccDebateLens];
 const traps={markup:'Treating a higher margin percentage as higher gross profit. Demand may fall.',breadth:'Counting more categories as free growth while ignoring the inventory funding.',depth:'Assuming deeper assortment always raises loyalty; it can freeze cash in stock.',private:'Treating a larger CLV valuation as proof of a lower WACC.',quality:'Assuming higher quality lowers WACC; unit costs and selling prices can both rise.'};
 const prompt={markup:'Would a higher markup lower WACC? Test gross-profit dollars after volume, not margin percentage.',breadth:'Would more categories lower WACC? Test contribution per dollar of funded stock, not the index alone.',depth:'Would deeper choice lower WACC? Test incremental basket and retention against inventory funding.',private:'Would a richer private-brand mix lower WACC? Separate differentiation/CLV value from credit improvement.',quality:'Would higher quality lower WACC? Pair quality with unit-cost discipline and check total contribution.'}[waccDebateGroup];
 return `<div class="review-chips">${WACC_DEBATE_LENSES.map(([key,label])=>`<button type="button" data-wacc-lens="${key}" class="${waccDebateLens===key?'selected':''}" aria-pressed="${waccDebateLens===key}">${esc(label)}</button>`).join('')}</div><div class="wacc-debate-grid"><div class="wacc-debate-card"><span class="evidence-label">${esc(WACC_DEBATE_LENSES.find(x=>x[0]===waccDebateLens)[1])}</span><h3>${esc(f.label)}</h3><p>${esc(content)}</p><p class="review-copy">Source: ${esc(p.source)}. Last input change: ${f.last_changed_round===null?'none':'R'+f.last_changed_round}; ${f.distinct_settings} distinct settings.</p></div><div class="review-takeaway"><strong>Debate prompt.</strong> ${esc(prompt)}<br><br><strong>Common trap.</strong> ${esc(traps[waccDebateGroup])}</div></div><div class="review-chips">${factors.map(x=>`<button type="button" data-wacc-inspect="${x.key}">Inspect ${esc(x.label)}</button>`).join('')}</div>${waccDebateGroup==='quality'?note(`Private and national quality inputs moved together and have stayed at 8 since R${a.constant_quality_since}. Their separate effects cannot be identified from this history.`):''}`;}
function waccDebatePanel(){return panel('The team’s debate: a guided factor lab','Pick one of the five debated factors. Switch between mechanism, benefit, risk and test. The buttons at the bottom jump to the actual input history for those factors.',`<div class="review-chips">${WACC_DEBATE_GROUPS.map(([key,label])=>`<button type="button" data-wacc-debate-group="${key}" class="${waccDebateGroup===key?'selected':''}" aria-pressed="${waccDebateGroup===key}">${esc(label)}</button>`).join('')}</div><div id="wacc-debate-detail">${waccDebateDetail()}</div>`);}
function waccReading(r){if(r===null||r===undefined)return 'Too little variation';if(r>=.5)return 'Moved together strongly';if(r>=.2)return 'Moved together weakly';if(r<=-.5)return 'Moved oppositely strongly';if(r<=-.2)return 'Moved oppositely weakly';return 'Little linear pattern';}
function waccAssociationPanel(){const a=data.wacc_analysis,corr=c=>c.r===null?'—':num(c.r),range=f=>f.leave_one_out_range?f.leave_one_out_range.map(num).join(' to '):'—';
 return panel('Correlation evidence—co-movement, not impact','Start with the plain reading. Open the statistical detail only if you need the exact correlation. This section is deliberately secondary to the factor lab and the 16-factor inspector.',
 `<div class="wacc-reading-key"><span><strong>+</strong> moved in the same direction</span><span><strong>−</strong> moved in opposite directions</span><span><strong>—</strong> too little variation to tell</span></div>`+
 table(['Factor','Latest input','Changed rounds','Same-period reading','Next-period reading'],a.factors.map(f=>[esc(f.label),factorValue(f.history.at(-1).value,f.unit),num(f.changed_rounds.length)+' / '+a.decision_transitions,waccReading(f.changes.r),waccReading(f.lagged_changes.r)]))+
 note('A “moved together” label is a descriptive clue, not evidence that the factor raises WACC. Most rounds changed several inputs at once, and a factor held constant can still interact with another factor. Do not sort this table into an investment priority.')+
 `<details><summary>Statistical detail: exact r, sample size and drop-one range</summary>${table(['Factor','Levels r / n','Same-period r / n','Next-period r / n','Drop-one-transition r range'],a.factors.map(f=>[esc(f.label),corr(f.levels)+' / '+f.levels.n,corr(f.changes)+' / '+f.changes.n,corr(f.lagged_changes)+' / '+f.lagged_changes.n,range(f)]))}<p>Levels use 7 points and can reflect time trends. Same-period changes use 6 transitions; next-period changes use 5 pairs and cannot evaluate the latest change. Unavailable means insufficient variation—not zero effect. Sixteen comparisons can produce large correlations by chance.</p></details>`+
 `<details><summary>Near-collinear input histories: why individual attribution is unreliable</summary>${table(['Input A','Input B','Levels correlation r'],a.collinear_pairs.map(p=>[esc(p.left),esc(p.right),num(p.r)]))}<p>Absolute r ≥ 0.98 is a descriptive screen, not a causal test. Dropping one transition can change the association.</p></details>`);}
function waccReweightResults(){const a=data.wacc_analysis,old=a.history.at(-2),now=a.history.at(-1),ke=$('#wacc-ke')?.valueAsNumber??14,kd=$('#wacc-kd')?.valueAsNumber??10,tax=$('#wacc-tax')?.valueAsNumber??35,mode=$('#wacc-weight-mode')?.value||'book_debt_weight';
 if(![ke,kd,tax].every(v=>Number.isFinite(v)&&v>=0&&v<=100))return note('Enter finite assumptions between 0 and 100%.');
 const kE=ke/100,kD=kd/100,t=tax/100,calc=w=>(1-w)*kE+w*kD*(1-t),before=calc(old[mode]),after=calc(now[mode]);
 return table(['Reweight-only illustration',`R${old.round}`,`R${now.round}`,'Change'],[['Debt weight proxy',pct(old[mode]),pct(now[mode]),signed(100*(now[mode]-old[mode]))+' pp'],['Illustrative WACC',pct(before),pct(after),signed(100*(after-before))+' pp'],['Reported simulation WACC',num(old.wacc)+'%',num(now.wacc)+'%',signed(now.wacc-old.wacc)+' pp']])+note('This holds assumed borrowing/equity rates and tax treatment fixed and changes only the financing-weight proxy. It is not a reconstruction or decomposition of actual WACC. If after-tax debt is cheaper than equity, replacing debt with equity can raise WACC even when debt and interest fall. Actual simulator weights and rates are unknown.');}
function waccImpactAnalysis(){const a=data.wacc_analysis,h=a.history,first=h[0],last=h.at(-1),prior=h.at(-2),wrap=s=>`<div class="wrap">${esc(s)}</div>`,corr=c=>c.r===null?'Unavailable':num(c.r),range=f=>f.leave_one_out_range?f.leave_one_out_range.map(num).join(' to '):'Unavailable';
 return head(`DECISION FACTORS → FINANCING · R0–R${data.current_round}`,'WACC impact analysis','Trace all 16 factors through margins, inventory, cash, credit ratios and financing weights. Mechanisms are documented; historical correlations are not causal effects.',offline?'':'<a class="button" href="/wacc-report" download>↓ Download WACC analysis HTML</a>')+
 `<div class="cards">${card('REPORTED WACC',num(last.wacc)+'%',signed(last.wacc-first.wacc)+' pp since R0')}${card('TOTAL DEBT',money(last.debt),signed(last.debt-prior.debt,money)+' since R'+prior.round)}${card('INTEREST COVER',num(last.interest_cover)+'×','EBIT / reported interest')}${card('DECISION TRANSITIONS',num(a.decision_transitions),num(a.periods)+' snapshots; '+a.factor_count+' decision factors')}</div>`+
 note(`<strong>Six rounds are useful, but not enough to isolate 16 effects.</strong> ${esc(a.identification)} We can use mechanisms, descriptive comparisons and sensitivity arithmetic—not certify that one factor caused a particular WACC change.`)+
 panel('What directly determines WACC?','MarketValue_Slides pp4–5: financing costs and weights; credit depends on liquidity, interest coverage and debt-to-equity.',`<p><strong>${esc(a.equation)}</strong></p>`+table(['Link','What is known','What is not known'],[['Cost of debt',wrap('The slides link credit to current ratio, interest coverage and debt/equity. Decisions act through operating performance and capital needs.'),wrap('Credit thresholds, actual borrowing-rate schedule and timing.')],['Cost of equity',wrap('The slides state AAA rate + 6 percentage points.'),wrap('Current AAA rate; no verified independent markup/quality/private-mix-to-equity-rate formula.')],['Financing weights',wrap('More debt or equity changes the blend. Lower debt is not mathematically guaranteed to mean lower WACC.'),wrap('Simulator weighting convention; book and market weights below are alternative proxies.')],['Brand and strategy',wrap('Customer durability supports future cash generation and the strategic horizon; private brands also support a separate valuation route.'),wrap('A direct Kahn-score-to-WACC coefficient. A higher market value/CLV is not proof of lower WACC.')]]))+
 panel('Our financial path: better credit metrics, but WACC is not monotonic','Raw simulation WACC is authoritative. Ratios below are calculated from reported statements.',historyLine('Reported WACC across all observed rounds',h.map(r=>r.round),[{label:'Reported WACC (%)',values:h.map(r=>r.wacc),color:'#7c3aed'}],n=>num(n)+'%')+table(['Round','WACC','Debt','Book equity','Current ratio','Interest cover','Debt / book equity','Inventory','Gross margin'],h.map(r=>['R'+r.round,num(r.wacc)+'%',money(r.debt),money(r.book_equity),num(r.current_ratio)+'×',num(r.interest_cover)+'×',num(r.debt_equity)+'×',money(r.inventory),pct(r.gross_margin)]))+note(`R${prior.round}→R${last.round}: debt ${money(prior.debt)} → ${money(last.debt)}, interest ${money(prior.interest)} → ${money(last.interest)}, yet reported WACC ${num(prior.wacc)}% → ${num(last.wacc)}%. This contradicts a simplistic “less debt always lowers WACC” rule, not the evidence of improved financing capacity.`))+
 waccModelPanel()+waccDebatePanel()+
 panel('Inspect any of the 16 decision factors','Start here when you want the actual numbers. Pick a factor, then read the mechanism, its input history and the round-by-round changes. The correlation table comes later and is optional.',`<div id="wacc-factor-panel"><label for="wacc-factor-select">Decision factor</label><select id="wacc-factor-select">${a.factors.map(f=>`<option value="${f.key}" ${f.key===waccFactorKey?'selected':''}>${esc(f.label)}</option>`).join('')}</select><div id="wacc-factor-detail">${waccFactorDetail()}</div></div>`)+
 waccAssociationPanel()+
 panel('Why debt repayment can coincide with higher WACC','Interactive arithmetic, not a simulator forecast. Defaults are explicitly hypothetical: equity cost 14%, debt cost 10%, tax 35%.',`<div class="review-controls"><div><label for="wacc-ke">Assumed cost of equity (%)</label><input id="wacc-ke" type="number" min="0" max="100" step="0.1" value="14"></div><div><label for="wacc-kd">Assumed cost of debt (%)</label><input id="wacc-kd" type="number" min="0" max="100" step="0.1" value="10"></div><div><label for="wacc-tax">Assumed tax rate (%)</label><input id="wacc-tax" type="number" min="0" max="100" step="0.1" value="35"></div><div><label for="wacc-weight-mode">Financing-weight proxy</label><select id="wacc-weight-mode"><option value="book_debt_weight">Debt / (debt + book equity)</option><option value="market_debt_weight">Debt / (debt + reported equity market value)</option></select></div></div><div id="wacc-reweight-results">${waccReweightResults()}</div>`)+
 panel('How to use this in the Round 7 debate','Minimizing WACC alone is not the winning objective; maximize sustainable market value and evaluate incremental ROIC against the financing cost.',`<ol class="strategy-steps"><li>For markup, test gross-profit dollars after volume response; do not treat margin percentage as demand.</li><li>For breadth/depth, require profitable customer benefit per dollar of stock and financing—not assumed savings per index point.</li><li>For private mix and quality, distinguish differentiation/CLV value from credit improvement, and pair quality with unit-cost discipline.</li><li>For every package, evaluate inventory, liquidity, interest coverage and financing weights together. Lower WACC can be accompanied by underinvestment; higher WACC does not automatically make an investment value-destroying.</li><li>Keep the confirmed ${money(data.strategy.funding.approved_budget,false)} budget. No workbook is edited by this analysis or its controls.</li></ol>`)+note(esc(a.boundary))+`<details><summary>WACC analysis sources</summary><ul>${a.sources.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></details>`+sources();}
document.addEventListener('change',e=>{if(e.target.id==='wacc-factor-select'){waccFactorKey=e.target.value;$('#wacc-factor-detail').innerHTML=waccFactorDetail();}if(e.target.id==='wacc-weight-mode')$('#wacc-reweight-results').innerHTML=waccReweightResults();});
document.addEventListener('click',e=>{const group=e.target.closest('[data-wacc-debate-group]'),lens=e.target.closest('[data-wacc-lens]'),inspect=e.target.closest('[data-wacc-inspect]'),kahn=e.target.closest('[data-kahn-quadrant]');
 if(kahn){kahnQuadrant=kahn.dataset.kahnQuadrant;document.querySelectorAll('[data-kahn-quadrant]').forEach(b=>{const on=b.dataset.kahnQuadrant===kahnQuadrant;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on));});const detail=$('#kahn-quadrant-detail');if(detail)detail.innerHTML=kahnQuadrantDetail();}
 if(group){waccDebateGroup=group.dataset.waccDebateGroup;$('#wacc-debate-detail').innerHTML=waccDebateDetail();}
 if(lens){waccDebateLens=lens.dataset.waccLens;$('#wacc-debate-detail').innerHTML=waccDebateDetail();}
 if(inspect){waccFactorKey=inspect.dataset.waccInspect;const select=$('#wacc-factor-select');if(select)select.value=waccFactorKey;const detail=$('#wacc-factor-detail');if(detail)detail.innerHTML=waccFactorDetail();$('#wacc-factor-panel')?.scrollIntoView({behavior:'smooth',block:'start'});}});
document.addEventListener('input',e=>{if(['wacc-ke','wacc-kd','wacc-tax'].includes(e.target.id))$('#wacc-reweight-results').innerHTML=waccReweightResults();});
